import{_ as e,o as d,c as l,ao as i}from"./chunks/framework.AQkxRU0n.js";const x=JSON.parse('{"title":"Julia API の実測対応表","description":"","frontmatter":{},"headers":[],"relativePath":"reference/support-matrix.md","filePath":"reference/support-matrix.md","lastUpdated":null}'),a={name:"reference/support-matrix.md"};function o(g,t,r,s,c,n){return d(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="Julia-API-の実測対応表" tabindex="-1">Julia API の実測対応表 <a class="header-anchor" href="#Julia-API-の実測対応表" aria-label="Permalink to &quot;Julia API の実測対応表 {#Julia-API-の実測対応表}&quot;">​</a></h1><p>通常配列の呼び出しが成功するかと、その入口を Colmat が提供するかを分けて記録します。 入口は Julia 1.13 のラッパー実装から選び、LBT の登録先を照合します。動的な呼び出し回数の計測やライブラリ内部を追跡したトレースではありません。</p><h2 id="検証条件" tabindex="-1">検証条件 <a class="header-anchor" href="#検証条件" aria-label="Permalink to &quot;検証条件 {#検証条件}&quot;">​</a></h2><ul><li><p>Julia: <code>1.13.3</code> / <code>x86_64-linux-gnu</code>。</p></li><li><p>Colmat ソース: <code>bc0dce2af48590dec20f99976ad7aee8b999a447</code>。</p></li><li><p>Rust colmat ソース: <code>e1c83482f5a61449d30e989808c3ba5f751ec391</code>。</p></li><li><p>Julia の BLAS 整数 ABI: <code>ilp64</code>。</p></li><li><p>Colmat 実行幅: <code>1</code>。</p></li><li><p>要素型は Float32 / Float64 / ComplexF32 / ComplexF64 の順。</p></li></ul><h2 id="実行結果" tabindex="-1">実行結果 <a class="header-anchor" href="#実行結果" aria-label="Permalink to &quot;実行結果 {#実行結果}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Julia API</th><th style="text-align:right;">Float32</th><th style="text-align:right;">Float64</th><th style="text-align:right;">ComplexF32</th><th style="text-align:right;">ComplexF64</th><th style="text-align:right;">主な入口の登録先</th><th style="text-align:right;">Rust 側の実装・接続</th></tr></thead><tbody><tr><td style="text-align:right;"><code>A * B</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">行列積</td></tr><tr><td style="text-align:right;"><code>mul!(C, A, B)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">行列積</td></tr><tr><td style="text-align:right;"><code>A * x</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">行列積</td></tr><tr><td style="text-align:right;"><code>dot(x, x)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>norm(x)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>BLAS.axpy!</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>UpperTriangular(A) \\ x</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>UpperTriangular(A) \\ B</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">Rust 互換層</td></tr><tr><td style="text-align:right;"><code>lu(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">partial_piv_lu（接続済み）</td></tr><tr><td style="text-align:right;"><code>lu(A) \\ x</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">LU solve（接続済み）</td></tr><tr><td style="text-align:right;"><code>qr(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">既存バックエンド</td><td style="text-align:right;">qr（未接続）</td></tr><tr><td style="text-align:right;"><code>qr(A, ColumnNorm())</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">既存バックエンド</td><td style="text-align:right;">col_piv_qr（未接続）</td></tr><tr><td style="text-align:right;"><code>svd(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">svd（接続済み）</td></tr><tr><td style="text-align:right;"><code>svd(A; alg=LinearAlgebra.QRIteration())</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">svd（接続済み）</td></tr><tr><td style="text-align:right;"><code>svdvals(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">SVD（接続済み）</td></tr><tr><td style="text-align:right;"><code>eigen(A)</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">eigen（接続済み）</td></tr><tr><td style="text-align:right;"><code>eigen(Hermitian(A))</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">self_adjoint_eigen（接続済み）</td></tr><tr><td style="text-align:right;"><code>cholesky(Hermitian(A))</code></td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">成功</td><td style="text-align:right;">Colmat</td><td style="text-align:right;">llt（接続済み）</td></tr></tbody></table><h2 id="入口シンボルと実際のライブラリ" tabindex="-1">入口シンボルと実際のライブラリ <a class="header-anchor" href="#入口シンボルと実際のライブラリ" aria-label="Permalink to &quot;入口シンボルと実際のライブラリ {#入口シンボルと実際のライブラリ}&quot;">​</a></h2><p>各行は上表と同じ API を確認しています。シンボルは上記4型の順です。</p><table tabindex="0"><thead><tr><th style="text-align:right;">Julia API</th><th style="text-align:right;">確認した入口</th><th style="text-align:right;">LBT の登録先</th></tr></thead><tbody><tr><td style="text-align:right;"><code>A * B</code></td><td style="text-align:right;"><code>sgemm_</code>, <code>dgemm_</code>, <code>cgemm_</code>, <code>zgemm_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>mul!(C, A, B)</code></td><td style="text-align:right;"><code>sgemm_</code>, <code>dgemm_</code>, <code>cgemm_</code>, <code>zgemm_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>A * x</code></td><td style="text-align:right;"><code>sgemv_</code>, <code>dgemv_</code>, <code>cgemv_</code>, <code>zgemv_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>dot(x, x)</code></td><td style="text-align:right;"><code>cblas_sdot</code>, <code>cblas_ddot</code>, <code>cblas_cdotc_sub</code>, <code>cblas_zdotc_sub</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>norm(x)</code></td><td style="text-align:right;"><code>snrm2_</code>, <code>dnrm2_</code>, <code>scnrm2_</code>, <code>dznrm2_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>BLAS.axpy!</code></td><td style="text-align:right;"><code>saxpy_</code>, <code>daxpy_</code>, <code>caxpy_</code>, <code>zaxpy_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>UpperTriangular(A) \\ x</code></td><td style="text-align:right;"><code>strsv_</code>, <code>dtrsv_</code>, <code>ctrsv_</code>, <code>ztrsv_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>UpperTriangular(A) \\ B</code></td><td style="text-align:right;"><code>strsm_</code>, <code>dtrsm_</code>, <code>ctrsm_</code>, <code>ztrsm_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>lu(A)</code></td><td style="text-align:right;"><code>sgetrf_</code>, <code>dgetrf_</code>, <code>cgetrf_</code>, <code>zgetrf_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>lu(A) \\ x</code></td><td style="text-align:right;"><code>sgetrs_</code>, <code>dgetrs_</code>, <code>cgetrs_</code>, <code>zgetrs_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>qr(A)</code></td><td style="text-align:right;"><code>sgeqrt_</code>, <code>dgeqrt_</code>, <code>cgeqrt_</code>, <code>zgeqrt_</code></td><td style="text-align:right;"><code>libopenblas64_.so</code></td></tr><tr><td style="text-align:right;"><code>qr(A, ColumnNorm())</code></td><td style="text-align:right;"><code>sgeqp3_</code>, <code>dgeqp3_</code>, <code>cgeqp3_</code>, <code>zgeqp3_</code></td><td style="text-align:right;"><code>libopenblas64_.so</code></td></tr><tr><td style="text-align:right;"><code>svd(A)</code></td><td style="text-align:right;"><code>sgesdd_</code>, <code>dgesdd_</code>, <code>cgesdd_</code>, <code>zgesdd_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>svd(A; alg=LinearAlgebra.QRIteration())</code></td><td style="text-align:right;"><code>sgesvd_</code>, <code>dgesvd_</code>, <code>cgesvd_</code>, <code>zgesvd_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>svdvals(A)</code></td><td style="text-align:right;"><code>sgesdd_</code>, <code>dgesdd_</code>, <code>cgesdd_</code>, <code>zgesdd_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>eigen(A)</code></td><td style="text-align:right;"><code>sgeevx_</code>, <code>dgeevx_</code>, <code>cgeevx_</code>, <code>zgeevx_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>eigen(Hermitian(A))</code></td><td style="text-align:right;"><code>ssyevr_</code>, <code>dsyevr_</code>, <code>cheevr_</code>, <code>zheevr_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr><tr><td style="text-align:right;"><code>cholesky(Hermitian(A))</code></td><td style="text-align:right;"><code>spotrf_</code>, <code>dpotrf_</code>, <code>cpotrf_</code>, <code>zpotrf_</code></td><td style="text-align:right;"><code>libcolmat_blas.so</code></td></tr></tbody></table><h2 id="判定の範囲" tabindex="-1">判定の範囲 <a class="header-anchor" href="#判定の範囲" aria-label="Permalink to &quot;判定の範囲 {#判定の範囲}&quot;">​</a></h2><ul><li><p>「成功」は、このプローブの小さな有限値入力で参照計算または分解の残差を満たしたことを表します。</p></li><li><p>行列積・求解・分解再構成の残差は、BLAS を呼ばないスカラーの積和で確認します。</p></li><li><p>「既存バックエンド」での成功は、Rust colmat の該当分解が接続済みであるという意味ではありません。</p></li><li><p>Rust 側の機能名は固定 revision の <code>faer/src/linalg/solvers.rs</code> で確認した対応候補です。未接続の Rust 関数をこのプローブが直接実行したとは主張しません。</p></li><li><p>この表は全 BLAS / LAPACK の網羅検証ではありません。特異行列、非有限値、一般化固有値、他 OS の結果も含みません。</p></li><li><p>LP64 の直接 ABI テストや負ストライド等の既存回帰テストとは別の、Julia 高水準 API の確認です。</p></li></ul><h2 id="再生成" tabindex="-1">再生成 <a class="header-anchor" href="#再生成" aria-label="Permalink to &quot;再生成 {#再生成}&quot;">​</a></h2><p>リポジトリのルートで、ビルド後の新しい Julia プロセスから実行します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/support_matrix.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output=docs/src/reference/support-matrix.md</span></span></code></pre></div><p>検証が失敗したときは表を上書きしません。呼び出しケースと検証方法は <code>test/support_matrix.jl</code> にあります。</p><h2 id="Householder-ABI-接続（#264）" tabindex="-1">Householder ABI 接続（#264） <a class="header-anchor" href="#Householder-ABI-接続（#264）" aria-label="Permalink to &quot;Householder ABI 接続（#264） {#Householder-ABI-接続（#264）}&quot;">​</a></h2><p>この追記は既存の Linux 実測表とは別の検証です。Julia 1.13.3 / <code>x86_64-apple-darwin</code>、colmat-rs <code>e1c83482f5a61449d30e989808c3ba5f751ec391</code> を使用しました。 <code>test/householder.jl</code> は <code>larf/larfx/larfy/larft/larfb/larfg/larfgp</code> の 4型・LP64/ILP64 の共有ライブラリ入口を具体的な C 署名で実行し、 28 canonical シンボルの LBT 登録先が Colmat であることを確認します。</p><p>生成は LAPACK の <code>I - tau*v*v&#39;</code>、実数 beta、LARFGP の非負 beta に合わせた Rust adapter です。colmat の実数係数・複素位相を保持する生成 API の単なる 逆数変換ではありません。適用は既存の native GEMV/SYMV/GEMM を使用します。 F/B、C/R の implicit unit diagonal を展開し、LARFT の三角因子を構成します。 LARFB は LAPACK 形式の外部因子も受け入れます。</p><p>検証は反射積・ユニタリ性・極小/極大尺度・複素 head・ゼロ係数・ 長さ1・正負 stride・左右・上下三角・外部 OpenBLAS の LARFT 因子を含みます。 LARFX の小次数では WORK を参照せず、LARFY は選択した三角領域だけを更新します。 これらの補助ルーチンには workspace query や INFO 引数はありません。 不正引数の診断は既存の <code>colmat_blas_last_error</code> 規約を使います。</p><p>LARFB は内部で basis と次数の二乗の明示的な反射行列を確保します。 呼び出し側の最小合法 WORK で動作しますが、作業領域だけを使う実装や LAPACK と同じ計算量・割り当て量を保証するものではありません。 この接続は Fortran ABI に限定し、LAPACKE は別タスクです。</p>',20)])])}const y=e(a,[["render",o]]);export{x as __pageData,y as default};
